35	const InvoiceFormSchema = z.object({
36	    gameDays: z.array(z.object({
37	        id: z.number().int().positive(),
38	        gameScheduled: z.boolean(),
39	        hallCostPounds: z.number().min(0),
40	    })),
41	});
42	
43	type InvoiceFormValues = z.infer<typeof InvoiceFormSchema>;
