52	interface InvoiceFormProps {
53	    year: number;
54	    month: number;
55	    gameDays: GameDayRow[];
56	    onUpdateGameDays: UpdateInvoiceGameDaysProxy;
57	    onRecordHallHire: RecordHallHireProxy;
58	}
