60	export const InvoiceForm = ({
61	    year,
62	    month,
63	    gameDays,
64	    onUpdateGameDays,
65	    onRecordHallHire,
66	}: InvoiceFormProps) => {
67	    const router = useRouter();
68	
69	    const form = useForm<InvoiceFormValues>({
70	        initialValues: {
71	            gameDays: gameDays.map((gd) => ({
72	                id: gd.id,
73	                gameScheduled: gd.gameScheduled,
74	                /* c8 ignore next — hallCost is a non-nullable DB column; the ?? 0 is a runtime safety net only */
75	                hallCostPounds: toPounds(gd.hallCost ?? 0),
76	            })),
77	        },
78	        validate: zod4Resolver(InvoiceFormSchema),
79	    });
80	
81	    const navigateMonth = (delta: number) => {
82	        let newMonth = month + delta;
83	        let newYear = year;
84	        if (newMonth < 1) {
85	            newMonth = 12;
86	            newYear -= 1;
87	        }
88	        if (newMonth > 12) {
89	            newMonth = 1;
90	            newYear += 1;
91	        }
92	        router.push(`/footy/admin/invoice?year=${newYear}&month=${newMonth}`);
93	    };
94	
95	    const handleSubmit = async (values: InvoiceFormValues) => {
96	        const notificationId = 'invoice-form';
97	
98	        notifications.show({
99	            id: notificationId,
100	            loading: true,
101	            title: 'Saving invoice',
102	            message: 'Saving game days and recording hall hire...',
103	            autoClose: false,
104	            withCloseButton: false,
105	        });
106	
107	        try {
108	            await onUpdateGameDays({
109	                gameDays: values.gameDays.map((gd) => ({
110	                    id: gd.id,
111	                    gameScheduled: gd.gameScheduled,
112	                })),
113	            });
114	
115	            await Promise.all(
116	                values.gameDays
117	                    .filter((gd) => gd.gameScheduled && gd.hallCostPounds > 0)
118	                    .map((gd) =>
119	                        onRecordHallHire({
120	                            amountPence: Math.round(gd.hallCostPounds * 100),
121	                            gameDayId: gd.id,
122	                            note: `Kelsey Kerridge invoice ${getFullMonthName(year, month)} ${year}`,
123	                        }),
124	                    ),
125	            );
126	
127	            const total = values.gameDays
128	                .filter((gd) => gd.gameScheduled)
129	                .reduce((sum, gd) => sum + gd.hallCostPounds, 0);
130	
131	            notifications.update({
132	                id: notificationId,
133	                color: 'teal',
134	                title: 'Invoice recorded',
135	                message: `Hall hire of £${total.toFixed(2)} recorded.`,
136	                icon: <IconCheck size={config.notificationIconSize} />,
137	                loading: false,
138	                autoClose: config.notificationAutoClose,
139	            });
140	        } catch (err) {
141	            captureUnexpectedError(err, {
142	                layer: 'client',
143	                component: 'InvoiceForm',
144	                action: 'submit',
145	                route: '/footy/admin/invoice',
146	            });
147	            notifications.update({
148	                id: notificationId,
149	                color: 'red',
150	                title: 'Error',
151	                message: err instanceof Error ? err.message : 'Failed to save invoice.',
152	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
153	                loading: false,
154	                autoClose: false,
155	                withCloseButton: true,
156	            });
157	        }
158	    };
159	
160	    const total = form.values.gameDays
161	        .filter((gd) => gd.gameScheduled)
162	        .reduce((sum, gd) => sum + (gd.hallCostPounds || 0), 0);
163	
164	    return (
165	        <Stack gap="xl" w="60%" mx="auto" my="xl">
166	            <Title order={2}>Invoice Check</Title>
167	
168	            <Group>
169	                <Button
170	                    variant="subtle"
171	                    leftSection={<IconChevronLeft size={16} />}
172	                    onClick={() => navigateMonth(-1)}
173	                >
174	                    {getFullMonthName(year, month - 1)}
175	                </Button>
176	                <Title order={3} style={{ flex: 1, textAlign: 'center' }}>
177	                    {getFullMonthName(year, month)} {year}
178	                </Title>
179	                <Button
180	                    variant="subtle"
181	                    rightSection={<IconChevronRight size={16} />}
182	                    onClick={() => navigateMonth(1)}
183	                >
184	                    {getFullMonthName(year, month + 1)}
185	                </Button>
186	            </Group>
187	
188	            {gameDays.length === 0 ? (
189	                <Text c="dimmed">No game days found for this month.</Text>
190	            ) : (
191	                <Box component="form" onSubmit={form.onSubmit(handleSubmit)}>
192	                    <Stack gap="sm">
193	                        <Table withTableBorder highlightOnHover>
194	                            <TableThead>
195	                                <TableTr>
196	                                    <TableTh>Date</TableTh>
197	                                    <TableTh>Game</TableTh>
198	                                    <TableTh>Hall Cost</TableTh>
199	                                </TableTr>
200	                            </TableThead>
201	                            <TableTbody>
202	                                {gameDays.map((gd, index) => (
203	                                    <TableTr key={gd.id}>
204	                                        <TableTd>
205	                                            <Text>{formatDate(gd.date)}</Text>
206	                                        </TableTd>
207	                                        <TableTd>
208	                                            <Checkbox
209	                                                aria-label={`Game scheduled for ${formatDate(gd.date)}`}
210	                                                {...form.getInputProps(`gameDays.${index}.gameScheduled`, { type: 'checkbox' })}
211	                                            />
212	                                        </TableTd>
213	                                        <TableTd>
214	                                            <NumberInput
215	                                                aria-label={`Hall cost for ${formatDate(gd.date)}`}
216	                                                prefix="£"
