224	                                                {...form.getInputProps(`gameDays.${index}.hallCostPounds`)}
225	                                            />
226	                                        </TableTd>
227	                                    </TableTr>
228	                                ))}
229	                            </TableTbody>
230	                        </Table>
231	
232	                        <Divider />
233	
234	                        <Group justify="space-between" align="center">
