47	const toResponseValues = (row: OutcomePlayerType): ResponseValues => ({
48	    response: row.response ?? null,
49	    goalie: !!row.goalie,
50	    // v8 ignore next -- comment is always a string in practice (Prisma default '')
51	    comment: row.comment ?? '',
52	});
53	
54	// Breakpoint at which each response row switches from a stacked mobile
55	// layout to a single-line row; kept as one constant so every field agrees.
56	const rowBreakpoint = 'lg';
57	
58	const responseGroupBarColor: Record<ResponseOption, MantineColor> = {
59	    [ResponseOption.Yes]: 'green.6',
60	    [ResponseOption.No]: 'red.6',
61	    [ResponseOption.Dunno]: 'yellow.6',
62	    [ResponseOption.Excused]: 'gray.6',
63	    [ResponseOption.Flaked]: 'gray.6',
64	    [ResponseOption.Injured]: 'gray.6',
65	    [ResponseOption.None]: 'gray.6',
66	};
67	
68	export const ResponsesForm = ({
69	    gameId,
70	    gameDate,
71	    responses,
72	    submitResponse,
73	}: ResponsesFormProps) => {
74	    const form = useForm<ResponsesFormValues>({
75	        initialValues: {
76	            byPlayerId: Object.fromEntries(responses.map((row) => [row.playerId, toResponseValues(row)])),
77	        },
78	    });
79	    const [savingId, setSavingId] = useState<number | null>(null);
80	    const [filter, setFilter] = useState('');
81	
82	    // Re-sync form values when the responses prop changes (e.g. after
83	    // revalidate / SSE refresh). Preserve any in-progress edits by only
84	    // overwriting rows whose form values still match the previous baseline.
85	    const prevResponsesRef = useRef(responses);
86	    useEffect(() => {
87	        const prevBaselineById = new Map(
88	            prevResponsesRef.current.map((row) => [row.playerId, toResponseValues(row)]),
89	        );
90	        for (const row of responses) {
91	            const newBaseline = toResponseValues(row);
92	            const oldBaseline = prevBaselineById.get(row.playerId) ?? newBaseline;
93	            const current = form.values.byPlayerId[row.playerId];
94	            const userEdited =
95	                !!current && (
96	                    current.response !== oldBaseline.response ||
97	                    current.goalie !== oldBaseline.goalie ||
98	                    current.comment !== oldBaseline.comment
99	                );
100	            if (!userEdited) {
101	                form.setFieldValue(`byPlayerId.${row.playerId}`, newBaseline);
102	            }
103	        }
104	        prevResponsesRef.current = responses;
105	        // eslint-disable-next-line react-hooks/exhaustive-deps -- form identity is stable; we only want to react to responses changes
106	    }, [responses]);
107	
108	    const isRowDirty = (row: OutcomePlayerType) => {
109	        const baseline = toResponseValues(row);
110	        // v8 ignore next -- form is always initialised from the same rows array
111	        const current = form.values.byPlayerId[row.playerId] ?? baseline;
112	
113	        return (
114	            baseline.response !== current.response ||
115	            baseline.goalie !== current.goalie ||
116	            baseline.comment !== current.comment
117	        );
118	    };
