import { Notifications } from '@mantine/notifications';
import type { Meta, StoryObj } from '@storybook/nextjs-vite';

import type { RecordHallHireProxy } from '@/types/actions/RecordHallHire';
import type { UpdateInvoiceGameDaysProxy } from '@/types/actions/UpdateInvoiceGameDays';

import { InvoiceForm } from './InvoiceForm';

const meta = {
    title: 'Admin/InvoiceForm/TEMP',
    component: InvoiceForm,
    decorators: [
        (Story) => (
            <>
                <Notifications />
                <Story />
            </>
        ),
    ],
    parameters: {
        layout: 'fullscreen',
    },
    tags: ['autodocs'],
} satisfies Meta<typeof InvoiceForm>;

export default meta;
type Story = StoryObj<typeof meta>;

const onUpdateGameDays: UpdateInvoiceGameDaysProxy = async () => Promise.resolve();
const onRecordHallHire: RecordHallHireProxy = async () =>
    Promise.resolve({ id: 1, gameDayId: 1, amountPence: 4700, note: 'test' } as never);

export const WithGameDays: Story = {
    args: {
        year: 2026,
        month: 8,
        gameDays: [
            { id: 1, date: '2026-08-04', gameScheduled: true, hallCost: 4700 },
            { id: 2, date: '2026-08-11', gameScheduled: false, hallCost: 4700 },
            { id: 3, date: '2026-08-18', gameScheduled: true, hallCost: 4700 },
            { id: 4, date: '2026-08-25', gameScheduled: true, hallCost: 4700 },
        ],
        onUpdateGameDays,
        onRecordHallHire,
    },
};

import { chromium } from 'playwright';

const storyUrl = 'http://localhost:6006/iframe.html?id=admin-invoiceform-temp--with-game-days&viewMode=story';
const outDir = '/private/tmp/claude-501/-Volumes-Development-next-www-toastboy/71f1cc98-cce9-43eb-8c5c-d6983cc5d284/scratchpad';

const browser = await chromium.launch();

const desktop = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await desktop.goto(storyUrl, { waitUntil: 'networkidle' });
await desktop.waitForSelector('text=Invoice Check');
await desktop.screenshot({ path: `${outDir}/invoice2-desktop.png`, fullPage: true });

const mobile = await browser.newPage({ viewport: { width: 375, height: 900 } });
await mobile.goto(storyUrl, { waitUntil: 'networkidle' });
await mobile.waitForSelector('text=Invoice Check');
await mobile.screenshot({ path: `${outDir}/invoice2-mobile.png`, fullPage: true });

const narrow = await browser.newPage({ viewport: { width: 320, height: 900 } });
await narrow.goto(storyUrl, { waitUntil: 'networkidle' });
await narrow.waitForSelector('text=Invoice Check');
await narrow.screenshot({ path: `${outDir}/invoice2-narrow.png`, fullPage: true });

// Also check that there's no horizontal overflow at 320px
const scrollWidth = await narrow.evaluate(() => document.documentElement.scrollWidth);
const clientWidth = await narrow.evaluate(() => document.documentElement.clientWidth);
console.log(`320px viewport: scrollWidth=${scrollWidth} clientWidth=${clientWidth} overflow=${scrollWidth > clientWidth}`);

await browser.close();
console.log('done');

