1	'use client';
2	
3	import {
4	    Anchor,
5	    Box,
6	    Button,
7	    Checkbox,
8	    Container,
9	    Divider,
10	    Flex,
11	    Group,
12	    NumberInput,
13	    Paper,
14	    Stack,
15	    Text,
16	    Title,
17	} from '@mantine/core';
18	import { useForm } from '@mantine/form';
19	import { notifications } from '@mantine/notifications';
20	import { IconAlertTriangle, IconCheck, IconChevronLeft, IconChevronRight } from '@tabler/icons-react';
21	import { zod4Resolver } from 'mantine-form-zod-resolver';
22	import { useRouter } from 'next/navigation';
23	import z from 'zod';
24	
25	import { config } from '@/lib/config';
26	import { formatDate, getFullMonthName } from '@/lib/dates';
27	import { toPounds } from '@/lib/money';
28	import { captureUnexpectedError } from '@/lib/observability/sentry';
29	import type { RecordHallHireProxy } from '@/types/actions/RecordHallHire';
30	import type { UpdateInvoiceGameDaysProxy } from '@/types/actions/UpdateInvoiceGameDays';
31	
32	const InvoiceFormSchema = z.object({
33	    gameDays: z.array(z.object({
34	        id: z.number().int().positive(),
35	        gameScheduled: z.boolean(),
36	        hallCostPounds: z.number().min(0),
37	    })),
38	});
39	
40	type InvoiceFormValues = z.infer<typeof InvoiceFormSchema>;
41	
42	// Breakpoint at which the submit button switches from a full-width mobile
43	// touch target to an inline fit-content button.
44	const actionsBreakpoint = 'sm';
45	
46	// Breakpoint at which each game-day row switches from a stacked mobile
47	// layout to a single-line row; kept as one constant so every field agrees.
48	const rowBreakpoint = 'sm';
49	
50	interface GameDayRow {
51	    id: number;
52	    date: string;
53	    gameScheduled: boolean;
54	    hallCost: number;
55	}
56	
57	interface InvoiceFormProps {
58	    year: number;
59	    month: number;
60	    gameDays: GameDayRow[];
61	    onUpdateGameDays: UpdateInvoiceGameDaysProxy;
62	    onRecordHallHire: RecordHallHireProxy;
63	}
64	
65	export const InvoiceForm = ({
66	    year,
67	    month,
68	    gameDays,
69	    onUpdateGameDays,
70	    onRecordHallHire,
71	}: InvoiceFormProps) => {
72	    const router = useRouter();
73	
74	    const form = useForm<InvoiceFormValues>({
75	        initialValues: {
76	            gameDays: gameDays.map((gd) => ({
77	                id: gd.id,
78	                gameScheduled: gd.gameScheduled,
79	                /* c8 ignore next — hallCost is a non-nullable DB column; the ?? 0 is a runtime safety net only */
80	                hallCostPounds: toPounds(gd.hallCost ?? 0),
81	            })),
82	        },
83	        validate: zod4Resolver(InvoiceFormSchema),
84	    });
85	
86	    const navigateMonth = (delta: number) => {
87	        let newMonth = month + delta;
88	        let newYear = year;
89	        if (newMonth < 1) {
90	            newMonth = 12;
91	            newYear -= 1;
92	        }
93	        if (newMonth > 12) {
94	            newMonth = 1;
95	            newYear += 1;
96	        }
97	        router.push(`/footy/admin/invoice?year=${newYear}&month=${newMonth}`);
98	    };
99	
100	    const handleSubmit = async (values: InvoiceFormValues) => {
101	        const notificationId = 'invoice-form';
102	
103	        notifications.show({
104	            id: notificationId,
105	            loading: true,
106	            title: 'Saving invoice',
107	            message: 'Saving game days and recording hall hire...',
108	            autoClose: false,
109	            withCloseButton: false,
110	        });
111	
112	        try {
113	            await onUpdateGameDays({
114	                gameDays: values.gameDays.map((gd) => ({
115	                    id: gd.id,
116	                    gameScheduled: gd.gameScheduled,
117	                })),
118	            });
119	
120	            await Promise.all(
121	                values.gameDays
122	                    .filter((gd) => gd.gameScheduled && gd.hallCostPounds > 0)
123	                    .map((gd) =>
124	                        onRecordHallHire({
125	                            amountPence: Math.round(gd.hallCostPounds * 100),
126	                            gameDayId: gd.id,
127	                            note: `Kelsey Kerridge invoice ${getFullMonthName(year, month)} ${year}`,
128	                        }),
129	                    ),
130	            );
131	
132	            const total = values.gameDays
133	                .filter((gd) => gd.gameScheduled)
134	                .reduce((sum, gd) => sum + gd.hallCostPounds, 0);
135	
136	            notifications.update({
137	                id: notificationId,
138	                color: 'teal',
139	                title: 'Invoice recorded',
140	                message: `Hall hire of £${total.toFixed(2)} recorded.`,
141	                icon: <IconCheck size={config.notificationIconSize} />,
142	                loading: false,
143	                autoClose: config.notificationAutoClose,
144	            });
145	        } catch (err) {
146	            captureUnexpectedError(err, {
147	                layer: 'client',
148	                component: 'InvoiceForm',
149	                action: 'submit',
150	                route: '/footy/admin/invoice',
151	            });
152	            notifications.update({
153	                id: notificationId,
154	                color: 'red',
155	                title: 'Error',
156	                message: err instanceof Error ? err.message : 'Failed to save invoice.',
157	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
158	                loading: false,
159	                autoClose: false,
160	                withCloseButton: true,
161	            });
162	        }
163	    };
164	
165	    const total = form.values.gameDays
166	        .filter((gd) => gd.gameScheduled)
167	        .reduce((sum, gd) => sum + (gd.hallCostPounds || 0), 0);
168	
169	    return (
170	        <Container fluid>
171	            <Paper w="100%" p="xl">
172	                <Stack gap="md">
173	                    <Stack align="flex-start" gap="xs">
174	                        <Title order={2}>Invoice Check</Title>
175	                        <Text c="dimmed">
176	                            Confirm which game days ran this month, then record the Kelsey Kerridge hall hire invoice.
177	                        </Text>
178	                    </Stack>
179	
180	                    <Group justify="space-between" wrap="wrap">
181	                        <Button
182	                            variant="subtle"
183	                            leftSection={<IconChevronLeft size={16} />}
184	                            onClick={() => navigateMonth(-1)}
185	                        >
186	                            {getFullMonthName(year, month - 1)}
187	                        </Button>
188	                        <Title order={3} flex={1} ta="center">
189	                            {getFullMonthName(year, month)} {year}
190	                        </Title>
191	                        <Button
192	                            variant="subtle"
193	                            rightSection={<IconChevronRight size={16} />}
194	                            onClick={() => navigateMonth(1)}
195	                        >
196	                            {getFullMonthName(year, month + 1)}
197	                        </Button>
198	                    </Group>
199	
200	                    {gameDays.length === 0 ? (
201	                        <Text c="dimmed">No game days found for this month.</Text>
202	                    ) : (
203	                        <Box component="form" onSubmit={form.onSubmit(handleSubmit)}>
204	                            <Stack gap="sm">
205	                                {gameDays.map((gd, index) => (
206	                                    <Flex
207	                                        key={gd.id}
208	                                        direction={{ base: 'column', [rowBreakpoint]: 'row' }}
209	                                        align={{ base: 'stretch', [rowBreakpoint]: 'center' }}
210	                                        gap="sm"
211	                                        bd="1px solid var(--mantine-color-gray-3)"
212	                                        p="sm"
213	                                        bdrs="sm"
214	                                    >
215	                                        <Text fw={600} w={{ base: '100%', [rowBreakpoint]: 140 }}>
216	                                            {formatDate(gd.date)}
217	                                        </Text>
218	                                        <Checkbox
219	                                            label="Game scheduled"
220	                                            aria-label={`Game scheduled for ${formatDate(gd.date)}`}
221	                                            {...form.getInputProps(`gameDays.${index}.gameScheduled`, { type: 'checkbox' })}
222	                                        />
223	                                        <NumberInput
224	                                            label="Hall cost"
225	                                            aria-label={`Hall cost for ${formatDate(gd.date)}`}
226	                                            prefix="£"
227	                                            decimalScale={2}
228	                                            disabled
229	                                            fixedDecimalScale
230	                                            allowNegative={false}
231	                                            hideControls
232	                                            min={0}
233	                                            w={{ base: '100%', [rowBreakpoint]: '8em' }}
234	                                            {...form.getInputProps(`gameDays.${index}.hallCostPounds`)}
235	                                        />
236	                                    </Flex>
237	                                ))}
238	
239	                                <Divider />
240	
241	                                <Group justify="space-between" align="center" wrap="wrap">
242	                                    <Text fw={600}>Total: £{total.toFixed(2)}</Text>
243	                                    <Button type="submit" w={{ base: '100%', [actionsBreakpoint]: 'fit-content' }}>
244	                                        Record invoice
245	                                    </Button>
246	                                </Group>
247	
248	                                <Text size="xs" c="dimmed">
249	                                    Current club balance can be viewed on the{' '}
250	                                    <Anchor href="/footy/books">Books</Anchor> page.
251	                                </Text>
252	                            </Stack>
253	                        </Box>
254	                    )}
255	                </Stack>
256	            </Paper>
257	        </Container>
258	    );
259	};
